START TRANSACTION;
INSERT INTO Branches(branch_name,ifsc_code,address,city,state,phone) VALUES('P2 synthetic','P2-TEST-IFSC','Synthetic','Test','Test','0000000090');
SET @p2_branch=LAST_INSERT_ID();
INSERT INTO Employees(branch_id,full_name,role,email,hire_date) VALUES(@p2_branch,'P2 synthetic teller','Teller','p2.teller@example.invalid','2020-01-01');
SET @p2_employee=LAST_INSERT_ID();
INSERT INTO Customers(full_name,dob,email,phone,address,id_proof_number,id_proof_type) VALUES('P2 synthetic','1990-01-01','p2.customer@example.invalid','0000000091','Synthetic','P2-SYNTHETIC-ID','Passport');
SET @p2_customer=LAST_INSERT_ID();
INSERT INTO Account_Types(type_name,interest_rate,min_balance) VALUES('P2 synthetic type',6.00,100.00);
SET @p2_type=LAST_INSERT_ID();
INSERT INTO Accounts(customer_id,branch_id,account_type_id,account_number,balance,opened_date) VALUES(@p2_customer,@p2_branch,@p2_type,'P2-SYNTHETIC-A',1000,'2026-01-01');
SET @p2_account=LAST_INSERT_ID();
SET @p2_ok=(SELECT COUNT(*)=0 FROM DB_User_Map WHERE BINARY SUBSTRING_INDEX(db_login,'@',1)=BINARY SUBSTRING_INDEX(USER(),'@',1));
CALL bank_lab.sp_assert_true(DATABASE(),'audit root initially unmapped',@p2_ok,'Disposable tests require an unmapped administrative login');
SET @p2_ok=(SELECT COUNT(*)=1 FROM Audit_Log WHERE table_name='Accounts' AND record_pk=CAST(@p2_account AS CHAR) AND action_type='INSERT' AND db_session_user=USER() AND actor_type='System' AND actor_employee_id IS NULL AND actor_customer_id IS NULL AND (old_value IS NULL AND JSON_LENGTH(new_value)=8 AND JSON_EXTRACT(new_value,'$.balance')=1000 AND JSON_UNQUOTE(JSON_EXTRACT(new_value,'$.status'))='Active'));
CALL bank_lab.sp_assert_true(DATABASE(),'Accounts INSERT audit',@p2_ok,'Expected audit contract');
UPDATE Accounts SET balance=1200,status='Frozen' WHERE account_id=@p2_account;
SET @p2_ok=(SELECT COUNT(*)=1 FROM Audit_Log WHERE table_name='Accounts' AND record_pk=CAST(@p2_account AS CHAR) AND action_type='UPDATE' AND db_session_user=USER() AND actor_type='System' AND actor_employee_id IS NULL AND actor_customer_id IS NULL AND (JSON_LENGTH(old_value)=8 AND JSON_LENGTH(new_value)=8 AND JSON_EXTRACT(old_value,'$.balance')=1000 AND JSON_EXTRACT(new_value,'$.balance')=1200 AND JSON_UNQUOTE(JSON_EXTRACT(old_value,'$.status'))='Active' AND JSON_UNQUOTE(JSON_EXTRACT(new_value,'$.status'))='Frozen'));
CALL bank_lab.sp_assert_true(DATABASE(),'Accounts UPDATE audit',@p2_ok,'Expected audit contract');
INSERT INTO Loans(customer_id,disbursement_account_id,principal_amount,interest_rate,tenure_months,status,disbursed_date) VALUES(@p2_customer,@p2_account,100,6,12,'Active','2026-01-01');
SET @p2_loan=LAST_INSERT_ID();
SET @p2_ok=(SELECT COUNT(*)=1 FROM Audit_Log WHERE table_name='Loans' AND record_pk=CAST(@p2_loan AS CHAR) AND action_type='INSERT' AND db_session_user=USER() AND actor_type='System' AND actor_employee_id IS NULL AND actor_customer_id IS NULL AND (old_value IS NULL AND JSON_LENGTH(new_value)=8 AND JSON_EXTRACT(new_value,'$.principal_amount')=100 AND JSON_UNQUOTE(JSON_EXTRACT(new_value,'$.status'))='Active'));
CALL bank_lab.sp_assert_true(DATABASE(),'Loans INSERT audit',@p2_ok,'Expected audit contract');
UPDATE Loans SET principal_amount=120,status='Closed' WHERE loan_id=@p2_loan;
SET @p2_ok=(SELECT COUNT(*)=1 FROM Audit_Log WHERE table_name='Loans' AND record_pk=CAST(@p2_loan AS CHAR) AND action_type='UPDATE' AND db_session_user=USER() AND actor_type='System' AND actor_employee_id IS NULL AND actor_customer_id IS NULL AND (JSON_LENGTH(old_value)=8 AND JSON_LENGTH(new_value)=8 AND JSON_EXTRACT(old_value,'$.principal_amount')=100 AND JSON_EXTRACT(new_value,'$.principal_amount')=120 AND JSON_UNQUOTE(JSON_EXTRACT(new_value,'$.status'))='Closed'));
CALL bank_lab.sp_assert_true(DATABASE(),'Loans UPDATE audit',@p2_ok,'Expected audit contract');
DELETE FROM Loans WHERE loan_id=@p2_loan;
SET @p2_ok=(SELECT COUNT(*)=1 FROM Audit_Log WHERE table_name='Loans' AND record_pk=CAST(@p2_loan AS CHAR) AND action_type='DELETE' AND db_session_user=USER() AND actor_type='System' AND actor_employee_id IS NULL AND actor_customer_id IS NULL AND (new_value IS NULL AND JSON_LENGTH(old_value)=8 AND JSON_EXTRACT(old_value,'$.principal_amount')=120));
CALL bank_lab.sp_assert_true(DATABASE(),'Loans DELETE audit',@p2_ok,'Expected audit contract');
DELETE FROM Accounts WHERE account_id=@p2_account;
SET @p2_ok=(SELECT COUNT(*)=1 FROM Audit_Log WHERE table_name='Accounts' AND record_pk=CAST(@p2_account AS CHAR) AND action_type='DELETE' AND db_session_user=USER() AND actor_type='System' AND actor_employee_id IS NULL AND actor_customer_id IS NULL AND (new_value IS NULL AND JSON_LENGTH(old_value)=8 AND JSON_EXTRACT(old_value,'$.balance')=1200 AND JSON_UNQUOTE(JSON_EXTRACT(old_value,'$.status'))='Frozen'));
CALL bank_lab.sp_assert_true(DATABASE(),'Accounts DELETE audit',@p2_ok,'Expected audit contract');
INSERT INTO Accounts(customer_id,branch_id,account_type_id,account_number,balance,opened_date) VALUES(@p2_customer,@p2_branch,@p2_type,'P2-AUDIT-TXN',1000,'2026-01-01');
SET @p2_account=LAST_INSERT_ID();
INSERT INTO Transactions(account_id,transaction_type,amount,balance_after,channel,status,reference_no) VALUES(@p2_account,'Deposit',1000,1000,'Online','Completed','P2-AUDIT-DEPOSIT');
SET @p2_txn=LAST_INSERT_ID();
SET @p2_ok=(SELECT COUNT(*)=1 FROM Audit_Log WHERE table_name='Transactions' AND record_pk=CAST(@p2_txn AS CHAR) AND action_type='INSERT' AND db_session_user=USER() AND actor_type='System' AND actor_employee_id IS NULL AND actor_customer_id IS NULL AND (old_value IS NULL AND JSON_LENGTH(new_value)=14 AND JSON_EXTRACT(new_value,'$.amount')=1000 AND JSON_EXTRACT(new_value,'$.balance_after')=1000 AND JSON_UNQUOTE(JSON_EXTRACT(new_value,'$.status'))='Completed'));
CALL bank_lab.sp_assert_true(DATABASE(),'Transactions INSERT audit',@p2_ok,'Expected audit contract');
INSERT INTO DB_User_Map(db_login,actor_type,employee_id) VALUES(USER(),'Employee',@p2_employee);
UPDATE Accounts SET balance=1300 WHERE account_id=@p2_account;
SET @p2_ok=(SELECT COUNT(*)=1 FROM Audit_Log WHERE table_name='Accounts' AND record_pk=CAST(@p2_account AS CHAR) AND action_type='UPDATE' AND JSON_EXTRACT(new_value,'$.balance')=1300 AND db_session_user=USER() AND actor_type='Employee' AND actor_employee_id=@p2_employee AND actor_customer_id IS NULL);
CALL bank_lab.sp_assert_true(DATABASE(),'mapped employee audit',@p2_ok,'Expected audit contract');
DELETE FROM DB_User_Map WHERE BINARY db_login=BINARY USER();
UPDATE Accounts SET balance=1400 WHERE account_id=@p2_account;
SET @p2_ok=(SELECT COUNT(*)=1 FROM Audit_Log WHERE table_name='Accounts' AND record_pk=CAST(@p2_account AS CHAR) AND action_type='UPDATE' AND JSON_EXTRACT(new_value,'$.balance')=1400 AND db_session_user=USER() AND actor_type='System');
CALL bank_lab.sp_assert_true(DATABASE(),'mapping removed becomes System',@p2_ok,'Expected audit contract');
SET @p2_ok=(SELECT COUNT(*)>=1 FROM bank_lab.Experiment_Log WHERE db_name=DATABASE() AND exp_id='SYS' AND event_type='AUDIT_TRIGGERS_INSTALLED' AND JSON_UNQUOTE(JSON_EXTRACT(detail,'$.db'))=DATABASE() AND JSON_CONTAINS_PATH(detail,'all','$.accounts_max_id','$.transactions_max_id','$.loans_max_id','$.audit_max_id','$.installed_at'));
CALL bank_lab.sp_assert_true(DATABASE(),'watermark scoped to selected database',@p2_ok,'Coverage begins at installation, not before');
ROLLBACK;
